CREATE TABLE research_methods(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, body TEXT NOT NULL CHECK(json_valid(body)), created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX research_methods_project ON research_methods(project_id,created_at);
CREATE TABLE task_corrections(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), task_id TEXT NOT NULL REFERENCES mission_tasks(id), body TEXT NOT NULL CHECK(json_valid(body)), reason TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TRIGGER notify_changed_research AFTER INSERT ON source_versions WHEN new.revision>1 BEGIN INSERT OR IGNORE INTO research_inbox(id,project_id,item_key,kind,title,body,created_at) SELECT lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-8'||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6))),new.project_id,'source-change:'||new.id,'task','资料有新版本，请检查相关研究','原有任务与引用仍保留原版本。请在研究计划中检查标记为材料已更新的步骤；不会自动发起付费重算。',new.created_at WHERE EXISTS(SELECT 1 FROM task_inputs ti JOIN source_versions v ON v.id=ti.version_id WHERE v.source_id=new.source_id AND v.id<>new.id); END;
DROP TRIGGER invalidate_task_source;
CREATE TRIGGER invalidate_task_source AFTER INSERT ON source_versions WHEN new.revision>1 BEGIN UPDATE mission_tasks SET status='stale',revision=revision+1,updated_at=new.created_at WHERE id IN (SELECT ti.task_id FROM task_inputs ti JOIN source_versions v ON v.id=ti.version_id WHERE v.source_id=new.source_id AND v.id<>new.id) AND status IN ('accepted','succeeded','review','ready','blocked','queued','running'); END;
